    # 2. Determine Background (most frequent)
    bg = max(counts, key=lambda k: counts[k])

    # Remove Background from counts to find Marker
    counts.pop(bg)

    # 3. Determine Marker (most frequent remaining color)
    if not counts:
        return grid
    marker = max(counts, key=lambda k: counts[k])

    # 4. Identify Pattern Pixels (all non-bg and non-marker)
    pattern_pixels = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != bg and val != marker:
                pattern_pixels.append((r, c, val))

