    # 5. Find the center of the pattern.
    # Heuristic: The pattern pixel with the most 4-connected neighbors belonging to the pattern.
    pattern_set = set((r, c) for r, c, val in pattern_pixels)

    best_center = None
    best_count = -1

    # Map original coords to neighbors count
    neighbor_counts = [0] * len(pattern_pixels)

    for i, (r, c, val) in enumerate(pattern_pixels):
        cnt = 0
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
