            best_center = (r, c)

    if best_center is None:
        return grid

    # 6. Build Pattern Offsets relative to center
    pattern_offsets = []
    for r, c, val in pattern_pixels:
        pattern_offsets.append((r - best_center[0], c - best_center[1], val))

